function [hd] = wheel_rate(tm, fr, st, nz, k_c)
%WHEEL_RATE  A wheel's momentum rate [N m]: the motor's torque tm less the uncompensated friction and the Stribeck excess st,
%   plus the torque noise nz.
%   tm: real[1] (passed a plain number)
%   fr: real[1] (passed a plain number)
%   st: real[1] (passed a plain number)
%   nz: real[1] (passed a plain number)
%   k_c: real[1] (passed a plain number)
%   returns hd: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    hd = 0;
    hd = (((tm - ((1 - k_c) * fr)) - st) + nz);
end
